export default function StateDrivenUI() {
  const [status, setStatus] = useState('idle');

  function renderContent() {
    if (status === 'loading') {
      return <p>Loading lessons…</p>;
    }

    if (status === 'success') {
      return <p>Lessons loaded.</p>;
    }

    if (status === 'error') {
      return <p>Could not load lessons.</p>;
    }

    return <p>Ready to load lessons.</p>;
