export default function FetchingPlayground() {
  const [endpoint, setEndpoint] = useState('/api/lessons');
  const [lessons, setLessons] = useState([]);
  const [status, setStatus] = useState('idle');
  const [error, setError] = useState(null);

  useEffect(() => {
    let cancelled = false;

    async function load() {
      setStatus('loading');
      setError(null);

      try {
        const response = await fetch(endpoint);

        if (!response.ok) {
          throw new Error(`HTTP ${response.status}`);
        }

        const data = await response.json();

        if (cancelled) {
          return;
        }

        setLessons(Array.isArray(data) ? data : data.lessons ?? []);
        setStatus('success');
      } catch (error) {
        if (cancelled) {
          return;
        }

        setError(error.message);
        setLessons([]);
        setStatus('error');
      }
    }

    load();

    return () => {
      cancelled = true;
    };
  }, [endpoint]);

  return (
    <div style={{
      padding: 16,
      background: '#0d1117',
      color: '#e6edf3',
      fontFamily: 'system-ui, sans-serif'
    }}>
