async function fetchWithRetry(
  request,
  maxRetries = 2
) {
  let attempt = 0;

  while (true) {
    try {
      return await request();
    } catch (error) {
      if (attempt >= maxRetries) {
        throw error;
      }

      attempt += 1;
    }
  }
}

